// ATS account passwords in the configured vault (config/vault.json): generated by op, stored with
// the project tag BEFORE a sign-up form is sent, and never put on a command line, in the repo,
// data/, logs or screenshots. adapter none creates nothing.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { makeVault, openVault, noVault, strongPassword, PASSWORD_RULES, VAULT_TAG, VaultDisabledError, opRun } from '../scripts/lib/adapters/vault.mjs';

const TEMPLATE = JSON.parse(readFileSync(new URL('../templates/workspace/config/vault.json', import.meta.url), 'utf8'));
const OP_CFG = { adapter: 'op', op: { account: 'example.1password.com', vault: 'Hunt', tag: 'jobba-hunt' } };
const EMAIL = 'jordan@example.com';
const TENANT = 'acme.wd5.myworkdayjobs.com';

// A fake op: records every call (argv and stdin) and answers from a script.
function fakeOp(script) {
  const calls = [];
  const items = [];
  const run = async (args, { input = null } = {}) => {
    calls.push({ args, input });
    const r = script(args, input, items);
    return { code: 0, stdout: '', stderr: '', ...r };
  };
  return { run, calls, items };
}
const after = (args, flag) => args[args.indexOf(flag) + 1];

test('strongPassword: 24 characters with an upper, a lower, a digit and a special character every time (common ATS password rules)', () => {
  for (let i = 0; i < 300; i++) {
    const p = strongPassword();
    assert.equal(p.length, 24);
    for (const re of PASSWORD_RULES) assert.match(p, re);
  }
  assert.notEqual(strongPassword(), strongPassword());
});

test('openVault: the shipped default is adapter none; it is never unlocked, finds nothing, and refuses to create or reveal (VaultDisabledError)', async () => {
  assert.equal(TEMPLATE.adapter, 'none');
  assert.equal(TEMPLATE.op.account, '', 'no default account name');
  for (const v of [openVault({ cfg: TEMPLATE }), openVault({ cfg: {} }), noVault()]) {
    assert.equal(v.kind, 'none');
    assert.equal(await v.unlocked(), false);
    assert.equal(await v.findLogin(`Workday ${TENANT}`), null);
    await assert.rejects(() => v.createLogin({ title: `Workday ${TENANT}`, url: `https://${TENANT}`, username: EMAIL }), VaultDisabledError);
    await assert.rejects(() => v.loginPassword('x'), VaultDisabledError);
  }
});

test('openVault: an unknown adapter is a config error, not a silent none', () => {
  assert.throws(() => openVault({ cfg: { adapter: 'keychain' } }), /unknown vault adapter/);
});

test('openVault: adapter op takes account, vault and tag from config', async () => {
  const op = fakeOp((args) => (args[1] === 'list' ? { stdout: '[]' } : {}));
  const v = openVault({ cfg: OP_CFG, run: op.run });
  assert.equal(v.kind, 'op');
  await v.findLogin('anything');
  const list = op.calls[0].args;
  assert.equal(after(list, '--account'), 'example.1password.com');
  assert.equal(after(list, '--vault'), 'Hunt');
  assert.equal(after(list, '--tags'), 'jobba-hunt');
});

test('openVault: adapter op with no account or vault leaves both to op (no --account, no --vault), and the tag defaults to the project tag', async () => {
  const op = fakeOp((args) => (args[1] === 'list' ? { stdout: '[]' } : args[0] === 'vault' ? { stdout: '[]' } : {}));
  const v = openVault({ cfg: { adapter: 'op', op: { account: '', vault: '', tag: '' } }, run: op.run });
  await v.unlocked();
  await v.findLogin('anything');
  for (const c of op.calls) {
    assert.ok(!c.args.includes('--account'), `op ${c.args.join(' ')}`);
    assert.ok(!c.args.includes('--vault'), `op ${c.args.join(' ')}`);
  }
  assert.equal(after(op.calls[1].args, '--tags'), VAULT_TAG);
});

test('vault: a locked or signed-out 1Password is reported as locked, and nothing is created', async () => {
  const op = fakeOp((args) => (args[0] === 'vault' ? { code: 1, stderr: '[ERROR] account is not signed in' } : {}));
  const v = makeVault(op.run, OP_CFG.op);
  assert.equal(await v.unlocked(), false);
  await assert.rejects(() => v.createLogin({ title: `Workday ${TENANT}`, url: `https://${TENANT}`, username: EMAIL }), /locked/);
  assert.ok(!op.calls.some((c) => c.args[0] === 'item' && c.args[1] === 'create'));
});

test('vault: createLogin has op generate the password itself (--category Login --generate-password, no stdin template, the password never on argv), in the configured vault and account, tagged, then reads it back before returning it (a stdin template failed with "provide the item category with --category")', async () => {
  const PW = 'Gq7#mZ2p!Lx9vR4t$Wk8yN3h';
  const op = fakeOp((args, input, items) => {
    if (args[0] === 'vault') return { stdout: JSON.stringify([{ id: 'v1', name: 'Hunt' }]) };
    if (args[0] === 'item' && args[1] === 'create') { items.push({ id: 'it1' }); return { stdout: JSON.stringify({ id: 'it1' }) }; }
    if (args[0] === 'item' && args[1] === 'get') return { stdout: `${PW}\n` };
    return { code: 1 };
  });
  const v = makeVault(op.run, OP_CFG.op);
  const { id, password } = await v.createLogin({ title: `Workday ${TENANT}`, url: `https://${TENANT}`, username: EMAIL, notes: 'Workday candidate account created by the jobba-hunt apply runner' });
  assert.equal(id, 'it1');
  assert.equal(password, PW);
  for (const c of op.calls) {
    assert.equal(c.input, null, `op ${c.args[0]} ${c.args[1]} got stdin`);
    assert.ok(!c.args.join(' ').includes(PW), `password on a command line: op ${c.args[0]} ${c.args[1]}`);
    assert.equal(after(c.args, '--account'), 'example.1password.com');
  }
  const create = op.calls.find((c) => c.args[0] === 'item' && c.args[1] === 'create');
  assert.ok(!create.args.includes('-'), 'no stdin template');
  assert.equal(after(create.args, '--category'), 'Login');
  assert.ok(create.args.some((a) => /^--generate-password=letters,digits,symbols,\d+$/.test(a)));
  assert.equal(after(create.args, '--vault'), 'Hunt');
  assert.equal(after(create.args, '--tags'), 'jobba-hunt');
  assert.equal(after(create.args, '--title'), `Workday ${TENANT}`);
  assert.equal(after(create.args, '--url'), `https://${TENANT}`);
  assert.ok(create.args.includes(`username=${EMAIL}`));
  assert.ok(create.args.includes('notesPlain=Workday candidate account created by the jobba-hunt apply runner'));
  // Read back from the vault (op item get ... --reveal) before the sign-up form may be sent.
  assert.ok(op.calls.some((c) => c.args[0] === 'item' && c.args[1] === 'get' && c.args.includes('--reveal')));
});

test('vault: a generated password missing a character class (upper, lower, digit, special) is regenerated in place with op item edit, and three misses are an error, not a sign-up', async () => {
  const reads = ['alllowercase-only', 'Gq7#mZ2p!Lx9vR4t$Wk8yN3h'];
  const op = fakeOp((args) => {
    if (args[0] === 'vault') return { stdout: '[]' };
    if (args[1] === 'create') return { stdout: JSON.stringify({ id: 'it3' }) };
    if (args[1] === 'edit') return { stdout: '{}' };
    if (args[1] === 'get') return { stdout: `${reads.shift()}\n` };
    return { code: 1 };
  });
  const { password } = await makeVault(op.run, OP_CFG.op).createLogin({ title: 'Workday y', url: 'https://globex.wd1.myworkdayjobs.com', username: EMAIL });
  assert.equal(password, 'Gq7#mZ2p!Lx9vR4t$Wk8yN3h');
  const edit = op.calls.find((c) => c.args[1] === 'edit');
  assert.equal(edit.args[2], 'it3');
  assert.ok(edit.args.some((a) => /^--generate-password=letters,digits,symbols,\d+$/.test(a)));

  const bad = fakeOp((args) => {
    if (args[0] === 'vault') return { stdout: '[]' };
    if (args[1] === 'create') return { stdout: JSON.stringify({ id: 'it4' }) };
    if (args[1] === 'edit') return { stdout: '{}' };
    if (args[1] === 'get') return { stdout: 'nouppercase1!\n' };
    return { code: 1 };
  });
  await assert.rejects(() => makeVault(bad.run, OP_CFG.op).createLogin({ title: 'Workday z', url: 'https://initech.wd1.myworkdayjobs.com', username: EMAIL }), /no account was created/);
});

test('vault: an empty read-back is an error, not a sign-up', async () => {
  const op = fakeOp((args) => {
    if (args[0] === 'vault') return { stdout: '[]' };
    if (args[1] === 'create') return { stdout: JSON.stringify({ id: 'it2' }) };
    if (args[1] === 'get') return { code: 1, stderr: 'not found' };
    return { code: 1 };
  });
  await assert.rejects(() => makeVault(op.run, OP_CFG.op).createLogin({ title: 'Workday x', url: 'https://hooli.wd1.myworkdayjobs.com', username: EMAIL }), /no account was created/);
});

test('opRun: a call without input gives op no stdin pipe (a piped stdin makes op read it as a template)', async () => {
  const { writeFileSync, mkdtempSync, chmodSync } = await import('node:fs');
  const { join } = await import('node:path');
  const { tmpdir } = await import('node:os');
  const dir = mkdtempSync(join(tmpdir(), 'opfake-'));
  const bin = join(dir, 'op');
  writeFileSync(bin, `#!/usr/bin/env node\nconst fs = require('fs');\nlet fifo = false;\ntry { const st = fs.fstatSync(0); fifo = st.isFIFO() || st.isSocket(); } catch {}\nprocess.stdout.write(JSON.stringify({ fifo }));\n`);
  chmodSync(bin, 0o755);
  const r = await opRun(bin)(['vault', 'list']);
  assert.equal(r.code, 0);
  assert.deepEqual(JSON.parse(r.stdout), { fifo: false });
});

test('vault: findLogin finds the tenant\'s item among the tagged items by title, and loginPassword reveals it', async () => {
  const op = fakeOp((args) => {
    if (args[1] === 'list') return { stdout: JSON.stringify([{ id: 'a', title: 'Workday globex.wd1.myworkdayjobs.com' }, { id: 'b', title: `Workday ${TENANT}` }]) };
    if (args[1] === 'get') return { stdout: 'S3cret!pw\n' };
    return { code: 1 };
  });
  const v = makeVault(op.run, OP_CFG.op);
  assert.equal(await v.findLogin(`Workday ${TENANT}`), 'b');
  assert.equal(await v.findLogin('Workday none.wd1.myworkdayjobs.com'), null);
  assert.equal(await v.loginPassword('b'), 'S3cret!pw');
  const list = op.calls.find((c) => c.args[1] === 'list');
  assert.equal(after(list.args, '--tags'), 'jobba-hunt');
});

